GET COLLECTION instruments; 
FILTER CASE WHERE .device_name != 'deposito B' AND .device_name IN .warehouse_location; 
GROUP PARTITION TRUE BY .device_name INTO .instrumentsByDevice

GET COLLECTION cases;
FILTER CASE WHERE .is_closed = TRUE AND .file_number != 'F-2023-02';
GROUP PARTITION TRUE BY .file_number INTO .legalCasesByFileNumber

GET COLLECTION tombe; 
JOIN OF COLLECTIONS tombe AS t, defunti AS d
CASE WHERE .t._id = .d._id;

GET COLLECTION spedizioni;
FILTER CASE WHERE .sdoganata = TRUE AND .peso_kg > 500 KEEP OTHERS;

GET COLLECTION ispettori;
FILTER CASE WHERE FIELD .contatto.email IS NOT NULL;

GET COLLECTION spedizioni;
GROUP PARTITION .peso_kg > 500 BY .sdoganata INTO .highValueShipments;

GET COLLECTION spedizioni;
GROUP PARTITION TRUE BY .contatto.email INTO .shipmentsByInspector
DROP GROUPING FIELDS;

GET COLLECTION spedizioni;
EXPAND UNPACK TRUE ARRAY .dimensioni_collo TO .dimensione;
EXPAND UNPACK TRUE ARRAY .righe TO .riga;

GET COLLECTION spedizioni;
FILTER CASE WHERE .dimensione.larghezza = 50 AND .dimensione.altezza = 30 EXPAND UNPACK TRUE ARRAY .riga TO .riga;

GET COLLECTION spedizioni;
FILTER CASE WHERE .category = 'electronics' AND .price < 100 KEEP OTHERS;

GET DICTIONARY ispettori@ft_it_073 AS inspector;
GET COLLECTION ispettori;
FILTER CASE WHERE FIELD .contatto.interno IS NOT NULL;

GET COLLECTION arnia; 
FILTER CASE WHERE .righe.id_macchinari IN (SELECT .mach_id FROM stabilimenti); 
JOIN OF COLLECTIONS arnia AS a, stabilimenti AS b 
CASE WHERE .a._id = .b.id_macchinari;

GET COLLECTION percorsi_raccolta; 
JOIN OF COLLECTIONS percorsi_raccolta AS a, cassonetti@ft_it_075 AS b 
CASE WHERE .a.id_percorsi_raccolta = .b._id; 
SAVE AS chaintemp1@ft_it_075; 
GET COLLECTION chaintemp1; 
EXPAND UNPACK TRUE ARRAY .a.items TO .item; 
SAVE AS chaintemp2@ft_it_075; 
USE DB ft_it_075 ON DEFAULT SERVER; 
JOIN OF COLLECTIONS chaintemp2@ft_it_075 AS c, dumpsters@ft_it_075 AS d 
CASE WHERE .c.item.item.product_id = .d._id;

GET COLLECTION percorsi_raccolta; 
JOIN OF COLLECTIONS cassonetti@ft_it_075 AS a, percorsi_raccolta@ft_it_075 AS b
CASE WHERE .a._id = .b.id_percorsi_raccolta;
FILTER CASE WHERE .a.sensore_attivo = TRUE OR .b.turno_notturno = TRUE;

GET COLLECTION percorsi_raccolta;
FILTER CASE WHERE .numero_fermate <= 32 AND .distanza_km = 118.9;
JOIN OF COLLECTIONS percorsi_raccolta AS a, cassonetti AS b CASE WHERE .a._id = .b.id_percorsi_raccolta;

GET COLLECTION routes;
FILTER CASE WHERE SIZE(.fermate) <= 32;
FILTER CASE WHERE .distanza_km = 118.9;
JOIN OF COLLECTIONS routes AS r, routes AS r2 CASE WHERE r._id = r2._id;
INTERSECT COLLECTIONS r, r2;

GET COLLECTION voyages; EXPAND UNPACK TRUE ARRAY .route_points TO .route; JOIN OF COLLECTIONS voyages AS v, route_stops AS r
CASE WHERE .v._id = .r._id
REMOVE DUPLICATES;

GET COLLECTION cases;
FILTER CASE WHERE .dossier_id != 'F-2023-02' OR .year >= 2011 AND .year <= 2023;
MERGE COLLECTIONS cases@jcoql_test, cases@jcoql_test REMOVE DUPLICATES;

GET COLLECTION depositoA;
FILTER CASE WHERE NOT (.voltage >= 194) AND .category = 'strumenti';
SAVE AS instrumenti@jcoql_test;
GET COLLECTION depositoA;
FILTER CASE WHERE .category = 'strumenti';
SAVE AS instrumentiTemp@jcoql_test;
INTERSECT COLLECTIONS instrumenti@jcoql_test, instrumentiTemp@jcoql_test;
